sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') return;

    var ga = new GlideAjax('x_1777185_home_s_0.Validate Attachments');
    ga.addParam('sysparm_name', 'getFileName');
    ga.addParam('sysparm_attachment_id', newValue);
    ga.getXMLAnswer(function(fileName) {
        fileName = fileName.toLowerCase();
        if (!(fileName.endsWith('.pdf') || !fileName.endsWith('.png') || !fileName.endsWith('.jpeg'))) {
            g_form.clearValue('attachment_file');
            g_form.showFieldMsg('attachment_file', 'Only PDF, PNG, or JPEG files are allowed.', 'error');
        }
    });
}
